    h, w = len(grid), len(grid[0])
    separators = [r for r in range(h) if len(set(grid[r])) == 1]

    # A full-width uniform row divides the canvas into horizontal bands.
    bands = []
    start = 0
    for r in separators + [h]:
        if start < r:
            bands.append((start, r))
        start = r + 1
    if len(bands) < 2:
        return [row[:] for row in grid]

    # The most common non-separator color is the band background.
    sep_colors = {grid[r][0] for r in separators}
    counts = {}
    for r in range(h):
        if r in separators:
            continue
        for value in grid[r]:
            if value not in sep_colors:
                counts[value] = counts.get(value, 0) + 1
    if not counts:
        return [row[:] for row in grid]
    background = max(counts, key=counts.get)

    # Use the densest band as the template, indexed relative to its top edge.
    sizes = {end - begin for begin, end in bands}
    if len(sizes) != 1:
        return [row[:] for row in grid]
    band_h = bands[0][1] - bands[0][0]
    patterns = []
