                 if grid[r][c] != background and grid[r][c] not in sep_colors}
        patterns.append(marks)
    template = max(patterns, key=len)

    out = [row[:] for row in grid]
    for begin, _ in bands:
        for (dr, c), value in template.items():
            out[begin + dr][c] = value
    return out
